import{_ as n,o as t,c as r,ae as a}from"./chunks/framework.Cqu5Y2mC.js";const d=JSON.parse('{"title":"Protokoll Sitzung 03","description":"","frontmatter":{},"headers":[],"relativePath":"05-Gemeinsam/2026-03-27-Protokoll.md","filePath":"05-Gemeinsam/2026-03-27-Protokoll.md"}'),l={name:"05-Gemeinsam/2026-03-27-Protokoll.md"};function i(o,e,s,m,h,u){return t(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="protokoll-sitzung-03" tabindex="-1">Protokoll Sitzung 03 <a class="header-anchor" href="#protokoll-sitzung-03" aria-label="Permalink to &quot;Protokoll Sitzung 03&quot;">​</a></h1><p><strong>Datum: 2026-03-27</strong><br><strong>Sitzung:</strong> <em><strong>03</strong></em><br><strong>Protokollführer: Daniel.Saracoglu</strong></p><p><strong>Teilnehmer:</strong><br><strong>Stadt:</strong> <em><strong>Samira Bieler</strong></em><br><strong>Technische Dienste:</strong> <em><strong>Herr Schleiger, Frau Feist</strong></em><br><strong>Sybit:</strong> <em><strong>Stephan Strittmatter, André Sommer</strong></em><br><strong>Lehrer:</strong> <em><strong>Stefan Martin</strong></em></p><p><strong>Schüler:</strong><br><em><strong>01-Betrieb: Artem, Huzaifa, Irakli, Marius</strong></em><br><em><strong>02-Hardware: Eray, Lukas</strong></em><br><em><strong>03-Software: Felix, Jannick, Theodor</strong></em><br><em><strong>04-Projektleitung: Daniel</strong></em></p><h2 id="besprochene-themen-inhalt" tabindex="-1">Besprochene Themen/ Inhalt: <a class="header-anchor" href="#besprochene-themen-inhalt" aria-label="Permalink to &quot;Besprochene Themen/ Inhalt:&quot;">​</a></h2><h3 id="_1-standorte-der-testmulleimer" tabindex="-1">1. Standorte der Testmülleimer <a class="header-anchor" href="#_1-standorte-der-testmulleimer" aria-label="Permalink to &quot;1. Standorte der Testmülleimer&quot;">​</a></h3><ul><li>In der Augustrufstr. &amp; Scheffelstr. befinden sich 3 Mülleimer die wir nutzen können. 1 alter &amp; zwei neue Mülleimer. <strong>ges.3</strong></li></ul><h3 id="_2-installation-messzyklen" tabindex="-1">2. Installation &amp; Messzyklen: <a class="header-anchor" href="#_2-installation-messzyklen" aria-label="Permalink to &quot;2. Installation &amp; Messzyklen:&quot;">​</a></h3><ul><li>Installation soll unterhalb des Laufbodens erfolgen.</li><li>70% der 100 Mülleimeier sind Schwenkt Mülleimer.</li><li>Einmal pro Tag zwischen 8 &amp; 9 Uhr Daten erfasssen genügt.</li><li>Der Sensor soll mit Schrauben an einer Halterung befestigt werden und dann eingesetzt weden.</li></ul><h3 id="_3-sinvolle-nutzung" tabindex="-1">3. Sinvolle Nutzung: <a class="header-anchor" href="#_3-sinvolle-nutzung" aria-label="Permalink to &quot;3. Sinvolle Nutzung:&quot;">​</a></h3><ul><li>Es macht Sinn später die Sensoren an abgelegene Mülleimer zu Installieren, an Fußgänger Zonen oder in der Innenstadt macht es weniger Sinn.</li></ul><h3 id="inhatlt" tabindex="-1">Inhatlt: <a class="header-anchor" href="#inhatlt" aria-label="Permalink to &quot;Inhatlt:&quot;">​</a></h3><ul><li>Neue Ziele für jede Gruppe vereinbart und diese an das Board in GitHub gestellt.</li></ul><hr><h2 id="ziele-bis-zur-nachsten-sitzung" tabindex="-1">Ziele bis zur nächsten Sitzung: <a class="header-anchor" href="#ziele-bis-zur-nachsten-sitzung" aria-label="Permalink to &quot;Ziele bis zur nächsten Sitzung:&quot;">​</a></h2><ul><li>Alle Ziele wurden an das GitHub Board geheftet.</li><li>Siehe GitHub Board im Projekt CitBin für weitere Informationen.</li></ul><hr><h2 id="_5-allgemein" tabindex="-1">5. Allgemein: <a class="header-anchor" href="#_5-allgemein" aria-label="Permalink to &quot;5. Allgemein:&quot;">​</a></h2><ul><li>Die älteren Mülleimer kann man per Hand öffnen.</li><li>Sensor leicht zum klauen</li><li>Provisorischer Test kann man mit Kleber machen</li></ul>',19)])])}const c=n(l,[["render",i]]);export{d as __pageData,c as default};
